mapper.select:
SELECT a.*, CASE WHEN r.id IS NOT NULL THEN 1 ELSE 0 END as is_read FROM sys_announcement a LEFT JOIN sys_announcement_read r ON a.announcement_id = r.announcement_id AND r.user_id = #{userId} WHERE a.del_flag = '0' AND a.status = '1' AND ( a.scope_type = 'ALL' OR (a.scope_type = 'DEPT' AND a.scope_value = #{deptId}) OR (a.scope_type = 'ROLE' AND
a.scope_value IN
#{role}
1 = 0
) ) ORDER BY a.priority DESC, a.create_time DESC
